insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('bouillon de poulet', 'Bouillon de poulet', array['soupe de poulet', 'soupe poulet vermicelle', 'bouillon de poule', 'soupe aux vermicelle']::text[], 'dish', $r$[{"title":"Soupe de poulet aux vermicelles","intro":"Le bouillon réconfortant au poulet, carottes et vermicelles, pour les soirs de rhume.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"chicken noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vermicelles","plural":"vermicelles","qty":80,"unit":"g","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets le poulet, l'oignon et le bouquet garni dans 1,5 litre d'eau salée et laisse frémir 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Retire le poulet et effiloche-le.","timer":null},{"text":"Ajoute les carottes et le poireau en rondelles, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les vermicelles et le poulet, et laisse 4 min.","timer":{"label":"Cuisson","min":4}},{"text":"Parsème de persil.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Bouillon de poulet au gingembre","intro":"Un bouillon parfumé à l'asiatique.","minutes":45,"calories":240,"difficulty":"Facile","imageSearch":"ginger chicken broth","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration asiatique","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"gingembre frais","p