insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tartare de boeuf', 'Tartare de bœuf', array['tartare', 'steak tartare', 'tartare de boeuf frite']::text[], 'dish', $r$[{"title":"Tartare de bœuf","intro":"Le bœuf cru haché au couteau, assaisonné aux câpres, cornichons, échalote et jaune d'œuf.","minutes":20,"calories":380,"difficulty":"Moyen","imageSearch":"steak tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"Bistrot français","serves":4,"items":[{"name":"bœuf extra-frais","plural":"bœuf extra-frais","qty":500,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"câpres","plural":"câpres","qty":1,"unit":"c. à s.","have":false},{"name":"cornichon","plural":"cornichons","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"sauce Worcestershire","plural":"sauce Worcestershire","qty":1,"unit":"c. à c.","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Hache le bœuf au couteau, le plus finement possible. Garde-le au frais.","timer":null},{"text":"Hache l'échalote, les câpres, les cornichons et le persil.","timer":null},{"text":"Mélange le bœuf avec la moutarde, la sauce Worcestershire et les condiments, sale et poivre.","timer":null},{"text":"Forme 4 portions et pose un jaune d'œuf sur chacune.","timer":null},{"text":"Sers aussitôt, bien frais, avec des frites ou une salade.","timer":null}],"variant":"La classique","change":""},{"title":"Tartare de bœuf à l'italienne","intro":"Un tartare frais à l'italienne, au basilic et parmesan.","minutes":20,"calories":400,"difficulty":"Moyen","imageSearch":"italian beef tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"bœuf extra-frais","plural":"bœuf extra-frais","qty":500,"unit":"g","have":false