insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('soupe thai', 'Soupe thaï', array['tom kha kai', 'tom yum', 'soupe thai coco', 'soupe coco citronnelle']::text[], 'dish', $r$[{"title":"Soupe thaï au poulet et lait de coco","intro":"Le tom kha kai : poulet dans un bouillon coco à la citronnelle et au citron vert.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"tom kha gai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette thaïlandaise","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"bouillon de volaille","plural":"bouillon de volaille","qty":1,"unit":"","have":false},{"name":"citronnelle","plural":"citronnelle","qty":2,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":2,"unit":"c. à s.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Porte à frémissement 50 cl d'eau avec le bouillon, la citronnelle écrasée et le gingembre en tranches.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le lait de coco et le poulet en fines lamelles, et laisse 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les champignons émincés et laisse 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Hors du feu, ajoute le jus des citrons verts et le nuoc-mâm.","timer":null},{"text":"Parsème de coriandre.","timer":null}],"variant":"La classique","change":""},{"title":"Soupe thaï aux crevettes","intro":"Une soupe thaï piquante et acidulée aux crevettes.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"tom yum shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette thaïlandaise","serves":4,"items":[{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":300,"unit":"g","have":false},{"name":"bouillon de volaille","plural":"bouillon de volaille","qty":1,"unit":"","have":false},{"name":"citronnelle","plural":"citronnelle","qty":2,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":150,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Porte à frémissement 1 litre d'eau avec le bouillon, la citronnelle et le piment.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les champignons et les tomates, et laisse 3 min.","timer":null},{"text":"Ajoute les crevettes et laisse 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Hors du feu, ajoute le jus des citrons verts et le nuoc-mâm.","timer":null}],"variant":"Crevettes","change":"Le tom yum : bouillon épicé aux crevettes."},{"title":"Soupe thaï végétarienne","intro":"Une soupe coco citronnelle au tofu.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"vegetarian thai coconut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":200,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"citronnelle","plural":"citronnelle","qty":2,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Porte à frémissement 50 cl d'eau avec le bouillon, la citronnelle et le gingembre.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le lait de coco, le tofu en dés et les champignons.","timer":null},{"text":"Laisse 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute le jus des citrons verts et la sauce soja.","timer":null}],"variant":"Végétarienne","change":"Avec du tofu et des légumes."}]$r$::jsonb, 'claude')
