insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('blini', 'Blinis', array['blini maison', 'blini saumon']::text[], 'dish', $r$[{"title":"Blinis maison","intro":"De petites crêpes épaisses et moelleuses, à garnir de crème et de saumon fumé.","minutes":40,"calories":180,"difficulty":"Facile","imageSearch":"blinis smoked salmon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":4,"unit":"tranches","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la farine, la levure, les jaunes d'œufs, le lait et le beurre fondu.","timer":null},{"text":"Monte les blancs en neige et incorpore-les.","timer":null},{"text":"Fais cuire des petits disques de pâte 1 min de chaque côté dans une poêle beurrée.","timer":{"label":"Poêle","min":2}},{"text":"Garnis chaque blini de crème, de saumon et d'aneth.","timer":null}],"variant":"La classique","change":""},{"title":"Blinis à la crème de chèvre","intro":"Des blinis apéritifs au chèvre frais.","minutes":35,"calories":170,"difficulty":"Facile","imageSearch":"blinis goat cheese","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"chèvre frais","plural":"chèvres frais","qty":150,"unit":"g","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false}],"steps":[{"text":"Prépare la pâte à blinis et fais-les cuire.","timer":{"label":"Poêle","min":2}},{"text":"Mélange le chèvre frais avec la ciboulette ciselée.","timer":null},{"text":"Garnis chaque blini.","timer":null},{"text":"Poivre et sers.","timer":null}],"variant":"Végétariens","change":"Garnis d'une crème au chèvre et aux herbes."},{"title":"Blinis au sarrasin","intro":"Des blinis au sarrasin, au goût plus rustique.","minutes":90,"calories":170,"difficulty":"Moyen","imageSearch":"buckwheat blinis","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration russe","serves":4,"items":[{"name":"farine de sarrasin","plural":"farine de sarrasin","qty":100,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":50,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":5,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":25,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":4,"unit":"tranches","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède, ajoute les farines et les jaunes.","timer":null},{"text":"Laisse lever 1 h.","timer":{"label":"Levée","min":60}},{"text":"Ajoute les blancs montés en neige.","timer":null},{"text":"Fais cuire les blinis 1 min de chaque côté et garnis-les de crème et de saumon.","timer":{"label":"Poêle","min":2}}],"variant":"Sarrasin","change":"Avec de la farine de sarrasin, à la russe."}]$r$::jsonb, 'claude')
