insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pain d epice', 'Pain d''épices', array['pain d epice maison', 'pain aux epice']::text[], 'dish', $r$[{"title":"Pain d'épices","intro":"Le pain d'épices moelleux au miel, parfumé à la cannelle, au gingembre et à l'anis.","minutes":80,"calories":280,"difficulty":"Facile","imageSearch":"french gingerbread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité de Dijon","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"miel","plural":"miels","qty":250,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":60,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"mélange quatre-épices","plural":"mélange quatre-épices","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C.","timer":null},{"text":"Chauffe le lait avec le miel et le sucre, sans faire bouillir.","timer":null},{"text":"Mélange la farine, la levure et les épices, puis ajoute le lait au miel et l'œuf.","timer":null},{"text":"Verse dans un moule à cake beurré et enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Laisse reposer un jour enveloppé : il est encore meilleur.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Pain d'épices à l'orange","intro":"Un pain d'épices de Noël parfumé à l'orange.","minutes":80,"calories":290,"difficulty":"Facile","imageSearch":"orange gingerbread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"miel","plural":"miels","qty":250,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"mélange quatre-épices","plural":"mélange quatre-épices","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C.","timer":null},{"text":"Chauffe le lait avec le miel et le zeste de l'orange.","timer":null},{"text":"Mélange la farine, la levure et les épices, puis le lait, l'œuf et le jus de l'orange.","timer":null},{"text":"Verse dans un moule et enfourne 1 h.","timer":{"label":"Four","min":60}}],"dessert":true,"variant":"Orange","change":"Avec du zeste et des écorces d'orange."},{"title":"Pain d'épices à l'ancienne","intro":"Le pain d'épices à l'ancienne, sans œuf.","minutes":75,"calories":270,"difficulty":"Facile","imageSearch":"eggless gingerbread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine de seigle","plural":"farine de seigle","qty":250,"unit":"g","have":false},{"name":"miel","plural":"miels","qty":250,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"bicarbonate","plural":"bicarbonate","qty":1,"unit":"c. à c.","have":false},{"name":"mélange quatre-épices","plural":"mélange quatre-épices","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C.","timer":null},{"text":"Chauffe le lait avec le miel.","timer":null},{"text":"Mélange la farine, le bicarbonate et les épices, puis le lait au miel.","timer":null},{"text":"Verse dans un moule et enfourne 1 h.","timer":{"label":"Four","min":60}}],"dessert":true,"variant":"Sans œuf","change":"Sans œuf, avec seulement du miel et du lait."}]$r$::jsonb, 'claude')
