insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tarte au chocolat', 'Tarte au chocolat', array['tarte chocolat', 'tarte au chocolat noir', 'tarte ganache']::text[], 'dish', $r$[{"title":"Tarte au chocolat","intro":"Une pâte sablée et une ganache au chocolat noir fondante.","minutes":50,"calories":450,"difficulty":"Moyen","imageSearch":"chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Fais cuire la pâte à blanc 20 min.","timer":{"label":"Four","min":20}},{"text":"Chauffe la crème et verse-la sur le chocolat en morceaux.","timer":null},{"text":"Mélange, puis ajoute le beurre et l'œuf battu.","timer":null},{"text":"Verse sur le fond de tarte et enfourne 10 min à 150 °C.","timer":{"label":"Four","min":10}},{"text":"Laisse refroidir au moins 1 h.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Tarte chocolat-caramel","intro":"Une tarte chocolat avec un cœur caramel.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"chocolate caramel tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"beurre demi-sel","plural":"beurre demi-sel","qty":40,"unit":"g","have":false}],"steps":[{"text":"Fais cuire la pâte à blanc 20 min à 180 °C.","timer":{"label":"Four","min":20}},{"text":"Fais un caramel avec le sucre, ajoute 10 cl de crème chaude et le beurre. Verse sur la pâte.","timer":null},{"text":"Chauffe le reste de la crème et fais-y fondre le chocolat.","timer":null},{"text":"Verse la ganache sur le caramel et laisse prendre 2 h au frais.","timer":null}],"dessert":true,"variant":"Caramel","change":"Avec une couche de caramel au beurre salé."},{"title":"Tarte chocolat sans cuisson","intro":"Une tarte chocolat express, sans four.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"no bake chocolate tart","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits secs","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Écrase les biscuits, mélange-les au beurre fondu et tasse dans un moule.","timer":null},{"text":"Chauffe la crème et verse-la sur le chocolat.","timer":null},{"text":"Mélange et verse sur la base.","timer":null},{"text":"Laisse prendre 2 h au frais.","timer":null}],"dessert":true,"variant":"Sans four","change":"Une base de biscuits et une ganache."}]$r$::jsonb, 'claude')
