insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('buche de noel', 'Bûche de Noël', array['buche', 'buche chocolat', 'buche roulee']::text[], 'dish', $r$[{"title":"Bûche de Noël au chocolat","intro":"Un biscuit roulé garni et recouvert de ganache au chocolat, pour le repas de Noël.","minutes":70,"calories":420,"difficulty":"Difficile","imageSearch":"chocolate yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"Tradition de Noël","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":250,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":40,"unit":"cl","have":false},{"name":"sucre glace","plural":"sucre glace","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fouette les œufs et le sucre jusqu'à ce que le mélange triple, puis ajoute la farine.","timer":null},{"text":"Étale sur une plaque couverte de papier cuisson et enfourne 8 min.","timer":{"label":"Four","min":8}},{"text":"Roule le biscuit chaud dans un torchon humide et laisse refroidir.","timer":null},{"text":"Chauffe la crème, verse-la sur le chocolat et laisse refroidir jusqu'à ce que la ganache épaississe.","timer":null},{"text":"Déroule le biscuit, garnis d'un tiers de ganache, roule et couvre du reste.","timer":null},{"text":"Dessine des stries à la fourchette et saupoudre de sucre glace.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Bûche aux marrons","intro":"La bûche à la crème de marrons, douce et fondante.","minutes":60,"calories":440,"difficulty":"Difficile","imageSearch":"chestnut yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"crème de marrons","plural":"crème de marrons","qty":300,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":20,"unit":"cl","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":100,"unit":"g","have":false}],"steps":[{"text":"Prépare le biscuit roulé et fais-le cuire 8 min à 200 °C.","timer":{"label":"Four","min":8}},{"text":"Roule-le dans un torchon humide.","timer":null},{"text":"Fouette la crème en chantilly et mélange-la à la crème de marrons.","timer":null},{"text":"Garnis le biscuit, roule-le et nappe de chocolat fondu.","timer":null}],"dessert":true,"variant":"Marrons","change":"Garnie de crème de marrons."},{"title":"Bûche glacée express","intro":"Une bûche glacée facile à préparer la veille.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"ice cream yule log","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"glace vanille","plural":"glace vanille","qty":50,"unit":"cl","have":false},{"name":"glace chocolat","plural":"glace chocolat","qty":50,"unit":"cl","have":false},{"name":"biscuits à la cuillère","plural":"biscuits à la cuillère","qty":12,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":100,"unit":"g","have":false}],"steps":[{"text":"Tapisse un moule à cake de film alimentaire.","timer":null},{"text":"Alterne la glace vanille ramollie, des biscuits et la glace chocolat.","timer":null},{"text":"Laisse prendre 6 h au congélateur.","timer":null},{"text":"Démoule et nappe de chocolat fondu juste avant de servir.","timer":null}],"dessert":true,"variant":"Glacée","change":"Avec de la glace et des biscuits, sans cuisson."}]$r$::jsonb, 'claude')
