insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gateau basque', 'Gâteau basque', array['gateau basque creme', 'gateau basque cerise']::text[], 'dish', $r$[{"title":"Gâteau basque à la crème","intro":"Une pâte sablée épaisse fourrée de crème pâtissière, à l'amande.","minutes":90,"calories":420,"difficulty":"Moyen","imageSearch":"gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":5,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":50,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":40,"unit":"cl","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":30,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Prépare la crème : chauffe le lait, fouette 2 œufs avec 80 g de sucre et la fécule, verse le lait, puis fais épaissir. Laisse refroidir.","timer":{"label":"Cuisson","min":5}},{"text":"Mélange le beurre et le reste du sucre, 2 œufs, la farine, la poudre d'amande et la levure.","timer":null},{"text":"Laisse la pâte 1 h au frais.","timer":null},{"text":"Préchauffe le four à 180 °C. Étale deux tiers de la pâte dans un moule, ajoute la crème et couvre du reste de pâte.","timer":null},{"text":"Dore au dernier œuf, raye à la fourchette et enfourne 40 min.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"La classique","change":""},{"title":"Gâteau basque à la cerise","intro":"Le gâteau basque fourré à la cerise noire.","minutes":80,"calories":430,"difficulty":"Moyen","imageSearch":"cherry gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":50,"unit":"g","have":false},{"name":"confiture de cerises noires","plural":"confiture de cerises noires","qty":300,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Mélange le beurre et le sucre, 2 œufs, la farine, la poudre d'amande et la levure. Laisse 1 h au frais.","timer":null},{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Étale deux tiers de la pâte dans un moule et garnis de confiture.","timer":null},{"text":"Couvre du reste de pâte, dore à l'œuf et enfourne 40 min.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"Cerise","change":"Fourré à la confiture de cerises noires."},{"title":"Gâteau basque au chocolat","intro":"Le gâteau basque version chocolat.","minutes":90,"calories":460,"difficulty":"Moyen","imageSearch":"chocolate gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":5,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":50,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":40,"unit":"cl","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":30,"unit":"g","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":100,"unit":"g","have":false}],"steps":[{"text":"Prépare une crème pâtissière et ajoute le chocolat en fin de cuisson. Laisse refroidir.","timer":{"label":"Cuisson","min":5}},{"text":"Prépare la pâte sablée et laisse-la 1 h au frais.","timer":null},{"text":"Monte le gâteau : pâte, crème, pâte.","timer":null},{"text":"Dore à l'œuf et enfourne 40 min à 180 °C.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"Chocolat","change":"Fourré d'une crème au chocolat."}]$r$::jsonb, 'claude')
