insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gateau aux pomme', 'Gâteau aux pommes', array['gateau pomme', 'gateau aux pomme moelleu', 'gateau invisible aux pomme', 'cake aux pomme']::text[], 'dish', $r$[{"title":"Gâteau moelleux aux pommes","intro":"Un gâteau tout simple, plein de pommes fondantes, pour le goûter.","minutes":60,"calories":280,"difficulty":"Facile","imageSearch":"apple cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":100,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"lait","plural":"laits","qty":5,"unit":"cl","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fouette les œufs et le sucre, puis ajoute la farine, la levure, le beurre fondu et le lait.","timer":null},{"text":"Épluche les pommes et coupe-les en morceaux, puis ajoute-les à la pâte.","timer":null},{"text":"Verse dans un moule beurré et enfourne 40 min.","timer":{"label":"Four","min":40}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Gâteau invisible aux pommes","intro":"Le gâteau aux couches de pommes fondantes, presque sans pâte.","minutes":75,"calories":220,"difficulty":"Moyen","imageSearch":"apple layer cake invisible","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":6,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":80,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":30,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange les œufs, le sucre, la farine, le lait et le beurre fondu.","timer":null},{"text":"Coupe les pommes en lamelles très fines et mélange-les à la pâte.","timer":null},{"text":"Tasse dans un moule à cake et enfourne 50 min.","timer":{"label":"Four","min":50}}],"dessert":true,"variant":"Invisible","change":"Des fines lamelles de pommes empilées avec très peu de pâte."},{"title":"Gâteau aux pommes et au yaourt","intro":"Le gâteau au yaourt aux pommes, mesuré au pot.","minutes":55,"calories":260,"difficulty":"Facile","imageSearch":"apple yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":3,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":6,"unit":"cl","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange le yaourt, le sucre, les œufs, la farine, la levure et l'huile.","timer":null},{"text":"Ajoute les pommes en dés.","timer":null},{"text":"Verse dans un moule et enfourne 40 min.","timer":{"label":"Four","min":40}}],"kids":true,"dessert":true,"variant":"Au yaourt","change":"Une base de gâteau au yaourt."}]$r$::jsonb, 'claude')
