insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('mousse au citron', 'Mousse au citron', array['mousse citron', 'mousse au citron leger']::text[], 'dish', $r$[{"title":"Mousse au citron","intro":"Une mousse légère et acidulée au citron, à servir en verrines.","minutes":25,"calories":250,"difficulty":"Facile","imageSearch":"lemon mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"citron","plural":"citrons","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":20,"unit":"cl","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fouette les jaunes, le sucre, la fécule, le jus et le zeste des citrons.","timer":null},{"text":"Fais épaissir à feu doux en remuant, puis laisse refroidir.","timer":{"label":"Cuisson","min":5}},{"text":"Fouette la crème en chantilly et monte les blancs en neige.","timer":null},{"text":"Incorpore délicatement la chantilly, puis les blancs, à la crème au citron.","timer":null},{"text":"Répartis en verrines et laisse 3 h au frais.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Mousse au citron vert et coco","intro":"Une mousse exotique, citron vert et coco.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"lime coconut mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"citron vert","plural":"citrons verts","qty":3,"unit":"","have":false},{"name":"crème de coco","plural":"crème de coco","qty":20,"unit":"cl","have":false},{"name":"lait concentré sucré","plural":"lait concentré sucré","qty":200,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":15,"unit":"cl","have":false}],"steps":[{"text":"Mélange le lait concentré avec le jus et le zeste des citrons verts.","timer":null},{"text":"Fouette la crème liquide et la crème de coco bien froides ensemble.","timer":null},{"text":"Incorpore délicatement au mélange citronné.","timer":null},{"text":"Répartis en verrines et laisse 3 h au frais.","timer":null}],"dessert":true,"variant":"Citron vert et coco","change":"Au citron vert et à la crème de coco."},{"title":"Mousse au citron express","intro":"Une mousse au citron express, sans œuf.","minutes":15,"calories":220,"difficulty":"Facile","imageSearch":"eggless lemon mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":300,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":20,"unit":"cl","have":false},{"name":"sucre glace","plural":"sucre glace","qty":60,"unit":"g","have":false}],"steps":[{"text":"Mélange le fromage blanc, le sucre glace, le jus et le zeste des citrons.","timer":null},{"text":"Fouette la crème en chantilly.","timer":null},{"text":"Incorpore-la délicatement.","timer":null},{"text":"Répartis en verrines et laisse 2 h au frais.","timer":null}],"dessert":true,"variant":"Sans œuf","change":"Au fromage blanc et à la crème."}]$r$::jsonb, 'claude')
