insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('rapide', 'recettes rapides', array['expres', 'plat rapide', 'vite fait']::text[], 'list', $r$[{"title":"Œufs brouillés crémeux","intro":"Des œufs brouillés doucement, crémeux et fondants.","minutes":10,"calories":240,"difficulty":"Facile","imageSearch":"creamy scrambled eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":8,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":2,"unit":"c. à s.","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Bats légèrement les œufs.","timer":null},{"text":"Fais-les cuire à feu doux avec le beurre en remuant sans arrêt 4 min.","timer":{"label":"Poêle","min":4}},{"text":"Retire du feu quand ils sont encore un peu coulants et ajoute la crème, sel, poivre et ciboulette.","timer":null}],"kids":true},{"title":"Escalopes de dinde à la crème","intro":"Des escalopes de dinde dorées, nappées d'une sauce crème aux champignons.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"turkey escalope cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":15,"unit":"g","have":false}],"steps":[{"text":"Fais dorer les escalopes 4 min de chaque côté dans le beurre et retire-les.","timer":{"label":"Poêle","min":8}},{"text":"Fais revenir l'échalote et les champignons 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute la crème et laisse 2 min.","timer":null},{"text":"Remets les escalopes dans la sauce 2 min.","timer":null}],"kids":true},{"title":"Spaghetti carbonara","intro":"La vraie carbonara : des œufs, du pecorino et du guanciale, sans crème.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"pecorino râpé","plural":"pecorino râpé","qty":60,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti dans l'eau bouillante salée.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer le guanciale en lamelles 5 min à la poêle, sans matière grasse.","timer":{"label":"Poêle","min":5}},{"text":"Bats les jaunes, l'œuf entier, le pecorino et beaucoup de poivre.","timer":null},{"text":"Égoutte les pâtes en gardant un peu d'eau de cuisson, et mets-les dans la poêle hors du feu.","timer":null},{"text":"Verse les œufs en mélangeant vite, avec un peu d'eau de cuisson pour obtenir une sauce crémeuse.","timer":null}]},{"title":"Saint-Jacques poêlées","intro":"Des noix de Saint-Jacques saisies au beurre, dorées dehors et nacrées dedans.","minutes":15,"calories":250,"difficulty":"Moyen","imageSearch":"seared scallops","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"noix de Saint-Jacques","plural":"noix de Saint-Jacques","qty":16,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Sèche bien les noix sur du papier absorbant.","timer":null},{"text":"Fais chauffer le beurre jusqu'à ce qu'il mousse.","timer":null},{"text":"Saisis les noix 1 min 30 de chaque côté sans les bouger.","timer":{"label":"Poêle","min":3}},{"text":"Arrose de jus de citron, sale et parsème de persil.","timer":null}]},{"title":"Côtes de porc à la moutarde","intro":"Des côtes de porc poêlées, avec une sauce crème à la moutarde à l'ancienne.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"pork chops mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"côte de porc","plural":"côtes de porc","qty":4,"unit":"","have":false},{"name":"moutarde à l'ancienne","plural":"moutarde à l'ancienne","qty":2,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"vin blanc","plural":"vin blanc","qty":5,"unit":"cl","have":false}],"steps":[{"text":"Fais dorer les côtes 5 min de chaque côté dans le beurre.","timer":{"label":"Poêle","min":10}},{"text":"Retire-les et fais revenir l'échalote hachée.","timer":null},{"text":"Déglace au vin blanc, ajoute la crème et la moutarde, et laisse 2 min.","timer":null},{"text":"Remets les côtes dans la sauce 2 min.","timer":null}],"kids":true},{"title":"Épinards à la crème","intro":"Des épinards fondus à la crème et à la muscade, en accompagnement.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"creamed spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pousses d'épinard",