il et au thym.","minutes":60,"calories":450,"difficulty":"Facile","imageSearch":"lemon chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":4,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les pommes de terre en quartiers et un citron en rondelles.","timer":null},{"text":"Mets tout dans un plat avec le poulet, l'ail, le thym, l'huile et le jus de l'autre citron.","timer":null},{"text":"Enfourne 45 min en arrosant de temps en temps.","timer":{"label":"Four","min":45}}]},{"title":"Poulet rôti","intro":"Un poulet doré et croustillant, avec un jus maison et des pommes de terre rôties.","minutes":90,"calories":620,"difficulty":"Facile","imageSearch":"roast chicken potatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet entier","plural":"poulets entiers","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":4,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C. Sors le poulet du réfrigérateur 30 min avant.","timer":n